{"operationName":"LandingPageAffiliateStatusQuery","query":"query LandingPageAffiliateStatusQuery($urlSuffix: String, $affiliateId: Long, $deviceId: String) {
  landingPageAffiliateStatus(
    urlSuffix: $urlSuffix
    affiliateId: $affiliateId
    deviceId: $deviceId
  ) {
    isHitOfferAffiliateStorefrontToappA
    isHitAnOfferFeOfferAffiliateStorefrontA
    region
    isSeller
  }
}
","variables":{"urlSuffix":"kesynaftalia","deviceId":"530C48828BA03F99355C60107CD922D7"}}

{"operationName":"getBaseInfoAndLinks","query":"query getBaseInfoAndLinks($urlSuffix: String!, $pageSize: String, $pageNum: String, $groupId: String, $linkNameKeyword: String) {
  landingPageBaseInfo(urlSuffix: $urlSuffix) {
    name
    headPortrait
    description
    region
    affiliateId
    shopLink
    background
    groupList {
      groupId
      groupName
      groupType
    }
    topFiveExternalLinkImages
  }
  landingPageLinkList(
    urlSuffix: $urlSuffix
    pageSize: $pageSize
    pageNum: $pageNum
    groupId: $groupId
    linkNameKeyword: $linkNameKeyword
  ) {
    totalCount
    linkList {
      linkId
      link
      linkName
      image
      linkType
      groupIds
    }
  }
}
","variables":{"urlSuffix":"kesynaftalia","pageSize":"40","pageNum":"1"}}

{"operationName":"getLinkLists","query":"query getLinkLists($urlSuffix: String!, $pageSize: String, $pageNum: String, $groupId: String, $linkNameKeyword: String) {
  landingPageLinkList(
    urlSuffix: $urlSuffix
    pageSize: $pageSize
    pageNum: $pageNum
    groupId: $groupId
    linkNameKeyword: $linkNameKeyword
  ) {
    totalCount
    linkList {
      linkId
      link
      linkName
      image
      linkType
      groupIds
    }
  }
}
","variables":{"urlSuffix":"kesynaftalia","pageSize":"20","pageNum":"3"}}
